class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        # 对于字符串的dp, 要意识到字符串一般都是从左往右遍历下标.
        # 那么对于结尾为i(开)的字符串s[0..i],可以分割意味着存在分割点j, 使得dp[j]=True且s[j..i]在wordDict中.
        wordDict = set(wordDict) # 会快很多
        n = len(s)
        dp = [False] * (n + 1)
        dp[0] = True # 空串
        for i in range(n + 1):
            for j in range(i):
                if dp[j] and s[j:i] in wordDict:
                    dp[i] = True
        return dp[n]
